from pathlib import Path
import shutil,re
root=Path(__file__).parent
out=root/'_site'
shutil.copytree(root/'public',out,dirs_exist_ok=True)
base='/franchise-pravo/'
form='https://docs.google.com/forms/d/e/1FAIpQLSfVaPryYmtoFkvWYJFNxxxBdB0LXeLTJM6kKQWEmS8lYbkl2g/viewform'
dialog=f'''<dialog id="consult-dialog" class="google-consult" aria-labelledby="consult-title"><button class="close-dialog" aria-label="Закрыть форму">×</button><div class="google-form-heading"><span class="eyebrow">Проверка с продавцом</span><h2 id="consult-title">Тестовая заявка</h2><p>Форма подключена к Google Таблице. Используйте вымышленные данные.</p><a href="{form}" target="_blank" rel="noopener">Открыть форму отдельно ↗</a></div><iframe title="Отправить тестовую заявку" data-src="{form}?embedded=true" referrerpolicy="strict-origin-when-cross-origin"></iframe></dialog>'''
for p in out.rglob('*.html'):
 s=p.read_text().replace('<body>','<body data-static="true">')
 s=s.replace('src="/app.js"','src="/google-form.js"')
 s=s.replace('Предпросмотр для Никиты · <a href="/privacy/">заявки остаются на этом устройстве</a>','Проверка с продавцом · <a href="/privacy/">тестовые заявки поступают в Google Таблицу</a>')
 s=re.sub(r'<dialog id="consult-dialog".*?</dialog>',lambda m:dialog,s,flags=re.S)
 s=s.replace('Обработка данных в предпросмотре','Данные тестовой заявки')
 s=s.replace('Это локальная версия сайта для проверки. Тестовая заявка сохраняется на компьютере, где запущен сайт. Передача юристу, в CRM и сторонние системы не подключена.','Это тестовая версия для проверки с продавцом. Встроенная Google Форма передаёт ответы в связанную закрытую Google Таблицу владельца формы. Юристу ответы не отправляются. Используйте вымышленные данные.')
 s=s.replace('Выбранная ситуация, имя, контакт, название клуба и описание, если вы их указали, дата заявки и отметка согласия. Используйте вымышленные тестовые данные и не вводите документы или конфиденциальные сведения.','Сохраняются время отправки, выбранная ситуация, имя, контакт, клуб или город и описание, если вы их указали. Адрес Google-аккаунта автоматически не собирается. Не вводите реальные персональные данные, документы или конфиденциальные сведения.')
 s=s.replace('Тестовые заявки доступны владельцу этого компьютера в локальном файле проекта. Он может удалить их после проверки. Внешних аналитических сервисов и рекламных трекеров в этой версии нет.','Ответы хранятся в Google Forms и связанной Google Таблице. Доступ к ответам имеет владелец формы; публичный просмотр ответов не включён. Владелец может удалить тестовые записи после проверки. При открытии встроенной формы браузер обращается к сервисам Google. При открытии сайта GitHub Pages получает технические данные запроса.')
 s=s.replace('Сайт находится в локальном предпросмотре. Действующие реквизиты исполнителя и реальный канал приёма заявок ещё не подключены. Отправленная тестовая форма никому не передаётся.','Подключён тестовый приём заявок через Google Forms в закрытую Google Таблицу владельца формы. Это проверка с продавцом; юридическая обработка обращений не запущена. Для коммерческого запуска нужны реквизиты исполнителя и правила обработки реальных персональных данных.')
 s=s.replace('href="/','href="'+base).replace('src="/','src="'+base)
 p.write_text(s)
(out/'.nojekyll').touch()
print(out)
